def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    centers=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r-1][c]==2 and grid[r+1][c]==2 and grid[r][c-1]==2 and grid[r][c+1]==2:
                centers.append((r,c))
    # Connect collinear diamond centers, coloring only the blank cells between their tips.
    for i,(r,c) in enumerate(centers):
        for rr,cc in centers[i+1:]:
            if r==rr and abs(cc-c)>2:
                step=1 if cc>c else -1
                for x in range(c+2*step,cc-1*step,step):
                    out[r][x]=1
            elif c==cc and abs(rr-r)>2:
                step=1 if rr>r else -1
                for y in range(r+2*step,rr-1*step,step):
                    out[y][c]=1
    return out
